import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const { default: StyleDictionary } = await import(
  pathToFileURL(`${process.cwd()}/lib/StyleDictionary.js`).href
);

const init = async (config) => {
  const sd = new StyleDictionary(config);
  await sd.hasInitialized;
  return sd;
};

const keysOf = (map) => [...map.keys()].sort();

test('expands strokeStyle dashArray into one indexed token per array item', async () => {
  const sd = await init({
    tokens: {
      stroke: {
        type: 'strokeStyle',
        value: { dashArray: ['0.5rem', '0.25rem'], lineCap: 'round' },
      },
    },
    expand: true,
  });

  // exactly one token per dashArray element, 1-based keys, no whole-array token left
  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{stroke.dashArray.1}',
    '{stroke.dashArray.2}',
    '{stroke.lineCap}',
  ]);

  const first = sd.tokenMap.get('{stroke.dashArray.1}');
  assert.strictEqual(first.key, '{stroke.dashArray.1}');
  assert.strictEqual(first.value, '0.5rem');
  assert.strictEqual(first.type, 'dimension');

  const second = sd.tokenMap.get('{stroke.dashArray.2}');
  assert.strictEqual(second.key, '{stroke.dashArray.2}');
  assert.strictEqual(second.value, '0.25rem');
  assert.strictEqual(second.type, 'dimension');

  const lineCap = sd.tokenMap.get('{stroke.lineCap}');
  assert.strictEqual(lineCap.value, 'round');
  assert.strictEqual(lineCap.type, 'lineCap');

  // the nested tokens object exposes the same itemized shape users consume
  assert.deepStrictEqual(Object.keys(sd.tokens.stroke.dashArray), ['1', '2']);
  assert.strictEqual(sd.tokens.stroke.dashArray[1].value, '0.5rem');
  assert.strictEqual(sd.tokens.stroke.dashArray[1].type, 'dimension');
  assert.strictEqual(sd.tokens.stroke.dashArray[1].key, '{stroke.dashArray.1}');
  assert.strictEqual(sd.tokens.stroke.dashArray[2].value, '0.25rem');
});

test('expands array-valued color components into one indexed token per item', async () => {
  const sd = await init({
    tokens: {
      brand: {
        type: 'color',
        value: { colorSpace: 'lab', components: [60.17, 90, -60.5] },
      },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{brand.colorSpace}',
    '{brand.components.1}',
    '{brand.components.2}',
    '{brand.components.3}',
  ]);

  const colorSpace = sd.tokenMap.get('{brand.colorSpace}');
  assert.strictEqual(colorSpace.value, 'lab');
  assert.strictEqual(colorSpace.type, 'colorSpace');

  const first = sd.tokenMap.get('{brand.components.1}');
  assert.strictEqual(first.key, '{brand.components.1}');
  assert.strictEqual(first.value, 60.17);
  assert.strictEqual(first.type, 'components');

  assert.strictEqual(sd.tokenMap.get('{brand.components.2}').value, 90);
  assert.strictEqual(sd.tokenMap.get('{brand.components.2}').type, 'components');
  assert.strictEqual(sd.tokenMap.get('{brand.components.3}').value, -60.5);
  assert.strictEqual(sd.tokenMap.get('{brand.components.3}').type, 'components');

  assert.strictEqual(sd.tokens.brand.components[1].value, 60.17);
  assert.strictEqual(sd.tokens.brand.components[1].type, 'components');
  assert.strictEqual(sd.tokens.brand.components[3].key, '{brand.components.3}');
});

test('expands transition timingFunction bezier array into one indexed token per control point', async () => {
  const sd = await init({
    tokens: {
      fade: {
        type: 'transition',
        value: {
          duration: '300ms',
          delay: '0ms',
          timingFunction: [0.42, 0, 0.58, 1],
        },
      },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{fade.delay}',
    '{fade.duration}',
    '{fade.timingFunction.1}',
    '{fade.timingFunction.2}',
    '{fade.timingFunction.3}',
    '{fade.timingFunction.4}',
  ]);

  const duration = sd.tokenMap.get('{fade.duration}');
  assert.strictEqual(duration.value, '300ms');
  assert.strictEqual(duration.type, 'duration');
  const delay = sd.tokenMap.get('{fade.delay}');
  assert.strictEqual(delay.value, '0ms');
  assert.strictEqual(delay.type, 'duration');

  const points = [0.42, 0, 0.58, 1];
  for (let i = 0; i < points.length; i++) {
    const key = `{fade.timingFunction.${i + 1}}`;
    const token = sd.tokenMap.get(key);
    assert.strictEqual(token.key, key);
    assert.strictEqual(token.value, points[i]);
    assert.strictEqual(token.type, 'cubicBezier');
  }

  assert.deepStrictEqual(Object.keys(sd.tokens.fade.timingFunction), ['1', '2', '3', '4']);
  assert.strictEqual(sd.tokens.fade.timingFunction[1].value, 0.42);
  assert.strictEqual(sd.tokens.fade.timingFunction[4].value, 1);
});

