test('expands tokens that reference an array-valued token', async () => {
  const sd = await init({
    tokens: {
      easing: { type: 'cubicBezier', value: [0.42, 0, 0.58, 1] },
      easingRef: { type: 'cubicBezier', value: '{easing}' },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{easing.1}',
    '{easing.2}',
    '{easing.3}',
