  for (let i = 0; i < bezierPoints.length; i++) {
    const token = sd.tokenMap.get(`{easingRef.${i + 1}}`);
    assert.strictEqual(token.value, bezierPoints[i]);
    assert.strictEqual(token.type, 'cubicBezier');
  }
