import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const { default: StyleDictionary } = await import(
  pathToFileURL(`${process.cwd()}/lib/StyleDictionary.js`).href
);

const init = async (config) => {
  const sd = new StyleDictionary(config);
  await sd.hasInitialized;
  return sd;
};

const keysOf = (map) => [...map.keys()].sort();

const plain = (value) => JSON.parse(JSON.stringify(value));

test('still expands plain object-value composite tokens exactly as before', async () => {
  const sd = await init({
    tokens: {
      border: {
        type: 'border',
        value: { width: '2px', style: 'solid', color: '#000' },
      },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{border.color}',
    '{border.style}',
    '{border.width}',
  ]);

  const color = sd.tokenMap.get('{border.color}');
  assert.strictEqual(color.value, '#000');
  assert.strictEqual(color.type, 'color');

  const style = sd.tokenMap.get('{border.style}');
  assert.strictEqual(style.value, 'solid');
  assert.strictEqual(style.type, 'strokeStyle');

  const width = sd.tokenMap.get('{border.width}');
  assert.strictEqual(width.value, '2px');
  assert.strictEqual(width.type, 'dimension');

  // assert the key set, not insertion order: object expansion output order follows
  // the input value's property order and must stay as-is before and after the fix
  assert.deepStrictEqual(
    Object.keys(sd.tokens.border).sort(),
    ['color', 'style', 'width'],
  );
});

test('still expands multi-value shadow tokens into indexed 1/2 groups', async () => {
  const sd = await init({
    tokens: {
      shade: {
        type: 'shadow',
        value: [
          { offsetX: '2px', offsetY: '4px', blur: '2px', spread: '0', color: '#000' },
          { offsetX: '10px', offsetY: '12px', blur: '4px', spread: '3px', color: '#ccc' },
        ],
      },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{shade.1.blur}',
    '{shade.1.color}',
    '{shade.1.offsetX}',
    '{shade.1.offsetY}',
    '{shade.1.spread}',
    '{shade.2.blur}',
    '{shade.2.color}',
    '{shade.2.offsetX}',
    '{shade.2.offsetY}',
    '{shade.2.spread}',
  ]);

  assert.strictEqual(sd.tokenMap.get('{shade.1.offsetX}').value, '2px');
  assert.strictEqual(sd.tokenMap.get('{shade.1.offsetX}').type, 'dimension');
  assert.strictEqual(sd.tokenMap.get('{shade.1.spread}').value, '0');
  assert.strictEqual(sd.tokenMap.get('{shade.1.color}').value, '#000');

  assert.strictEqual(sd.tokenMap.get('{shade.2.offsetX}').value, '10px');
  assert.strictEqual(sd.tokenMap.get('{shade.2.offsetX}').type, 'dimension');
  assert.strictEqual(sd.tokenMap.get('{shade.2.blur}').value, '4px');
  assert.strictEqual(sd.tokenMap.get('{shade.2.color}').value, '#ccc');

  assert.deepStrictEqual(Object.keys(sd.tokens.shade), ['1', '2']);
  assert.strictEqual(sd.tokens.shade[1].offsetX.value, '2px');
  assert.strictEqual(sd.tokens.shade[2].color.value, '#ccc');
});

test('still expands gradient tokens (arrays of objects) into indexed groups', async () => {
  const sd = await init({
    tokens: {
      grad: {
        type: 'gradient',
        value: [
          { color: '#000', position: 0 },
          { color: '#fff', position: 1 },
        ],
      },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{grad.1.color}',
    '{grad.1.position}',
    '{grad.2.color}',
    '{grad.2.position}',
  ]);

  assert.strictEqual(sd.tokenMap.get('{grad.1.position}').value, 0);
  assert.strictEqual(sd.tokenMap.get('{grad.1.position}').type, 'number');
  assert.strictEqual(sd.tokenMap.get('{grad.2.color}').value, '#fff');
  assert.strictEqual(sd.tokenMap.get('{grad.2.color}').type, 'color');
  assert.strictEqual(sd.tokenMap.get('{grad.2.position}').value, 1);
});

test('still expands DTCG object-value tokens and references to them', async () => {
  const sd = await init({
    tokens: {
      border: { $type: 'border', $value: { width: '2px', style: 'solid', color: '#000' } },
      borderRef: { $type: 'border', $value: '{border}' },
    },
    expand: true,
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{border.color}',
    '{border.style}',
    '{border.width}',
    '{borderRef.color}',
    '{borderRef.style}',
    '{borderRef.width}',
  ]);

  assert.strictEqual(sd.tokenMap.get('{border.width}').$value, '2px');
  assert.strictEqual(sd.tokenMap.get('{border.width}').$type, 'dimension');
  assert.strictEqual(sd.tokenMap.get('{border.style}').$value, 'solid');
  assert.strictEqual(sd.tokenMap.get('{border.style}').$type, 'strokeStyle');

  assert.strictEqual(sd.tokenMap.get('{borderRef.color}').$value, '#000');
  assert.strictEqual(sd.tokenMap.get('{borderRef.width}').$value, '2px');
  assert.strictEqual(sd.tokenMap.get('{borderRef.width}').$type, 'dimension');

  assert.strictEqual(plain(sd.tokens.borderRef.style.$value), 'solid');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const { default: StyleDictionary } = await import(
  pathToFileURL(`${process.cwd()}/lib/StyleDictionary.js`).href
);

const init = async (config) => {
  const sd = new StyleDictionary(config);
  await sd.hasInitialized;
  return sd;
};

const keysOf = (map) => [...map.keys()].sort();

const plain = (value) => JSON.parse(JSON.stringify(value));

const arrayInput = () => ({
  stroke: {
    type: 'strokeStyle',
    value: { dashArray: ['0.5rem', '0.25rem'], lineCap: 'round' },
  },
  easing: { type: 'cubicBezier', value: [0.42, 0, 0.58, 1] },
});

test('leaves array values untouched by default when no expand config is given', async () => {
  const input = arrayInput();
  const expected = plain(input);
  const sd = await init({ tokens: input });

  assert.deepStrictEqual(keysOf(sd.tokenMap), ['{easing}', '{stroke}']);
  assert.deepStrictEqual(plain(sd.tokens), expected);

  const stroke = sd.tokenMap.get('{stroke}');
  assert.strictEqual(stroke.type, 'strokeStyle');
  assert.deepStrictEqual(stroke.value.dashArray, ['0.5rem', '0.25rem']);
  assert.deepStrictEqual(plain(stroke.value), {
    dashArray: ['0.5rem', '0.25rem'],
    lineCap: 'round',
  });

  assert.deepStrictEqual(sd.tokenMap.get('{easing}').value, [0.42, 0, 0.58, 1]);
  assert.deepStrictEqual(plain(sd.tokens.easing.value), [0.42, 0, 0.58, 1]);
});

test('leaves array values untouched when expand is explicitly false', async () => {
  const input = arrayInput();
  const expected = plain(input);
  const sd = await init({ tokens: input, expand: false });

  assert.deepStrictEqual(keysOf(sd.tokenMap), ['{easing}', '{stroke}']);
  assert.deepStrictEqual(plain(sd.tokens), expected);

  const stroke = sd.tokenMap.get('{stroke}');
  assert.deepStrictEqual(stroke.value.dashArray, ['0.5rem', '0.25rem']);
  assert.deepStrictEqual(sd.tokenMap.get('{easing}').value, [0.42, 0, 0.58, 1]);
});

test('platform export without an expand config keeps array values untouched', async () => {
  const sd = await init({
    tokens: arrayInput(),
    platforms: { css: {} },
  });

  const { tokenMap } = await sd.getPlatformTokens('css');
  assert.deepStrictEqual(keysOf(tokenMap), ['{easing}', '{stroke}']);

  const stroke = tokenMap.get('{stroke}');
  assert.strictEqual(stroke.type, 'strokeStyle');
  assert.deepStrictEqual(stroke.value.dashArray, ['0.5rem', '0.25rem']);
  assert.deepStrictEqual(stroke.path, ['stroke']);

  const easing = tokenMap.get('{easing}');
  assert.strictEqual(easing.type, 'cubicBezier');
  assert.deepStrictEqual(easing.value, [0.42, 0, 0.58, 1]);
  assert.deepStrictEqual(easing.path, ['easing']);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const { default: StyleDictionary } = await import(
  pathToFileURL(`${process.cwd()}/lib/StyleDictionary.js`).href
);

const init = async (config) => {
  const sd = new StyleDictionary(config);
  await sd.hasInitialized;
  return sd;
};

const keysOf = (map) => [...map.keys()].sort();

const plain = (value) => JSON.parse(JSON.stringify(value));

const mixedTokens = () => ({
  stroke: {
    type: 'strokeStyle',
    value: { dashArray: ['0.5rem', '0.25rem'], lineCap: 'round' },
  },
  fade: {
    type: 'transition',
    value: {
      duration: '300ms',
      delay: '0ms',
      timingFunction: [0.42, 0, 0.58, 1],
    },
  },
});

test('expand.include selects which tokens have their array values itemized', async () => {
  const sd = await init({
    tokens: mixedTokens(),
    // cover both the composite type and dashArray's mapped type (dimension) so the
    // filter admits the strokeStyle token and its expanded array items alike
    expand: { include: ['strokeStyle', 'dimension'] },
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{fade}',
    '{stroke.dashArray.1}',
    '{stroke.dashArray.2}',
    '{stroke.lineCap}',
  ]);

  const dash1 = sd.tokenMap.get('{stroke.dashArray.1}');
  assert.strictEqual(dash1.key, '{stroke.dashArray.1}');
  assert.strictEqual(dash1.value, '0.5rem');
  assert.strictEqual(dash1.type, 'dimension');
  const dash2 = sd.tokenMap.get('{stroke.dashArray.2}');
  assert.strictEqual(dash2.value, '0.25rem');
  assert.strictEqual(dash2.type, 'dimension');
  assert.strictEqual(sd.tokenMap.get('{stroke.lineCap}').value, 'round');

  // excluded token keeps its object value with the array intact
  const fade = sd.tokenMap.get('{fade}');
  assert.strictEqual(fade.type, 'transition');
  assert.deepStrictEqual(plain(fade.value), {
    duration: '300ms',
    delay: '0ms',
    timingFunction: [0.42, 0, 0.58, 1],
  });
});

test('expand.include still keeps excluded nested composite values (containing arrays) intact', async () => {
  const sd = await init({
    tokens: {
      border: {
        type: 'border',
        value: {
          color: { colorSpace: 'lab', components: [60.17, 90, -60.5] },
          width: '4px',
          style: 'solid',
        },
      },
    },
    expand: { include: ['border'] },
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{border.color}',
    '{border.style}',
    '{border.width}',
  ]);

  const color = sd.tokenMap.get('{border.color}');
  assert.strictEqual(color.type, 'color');
  assert.deepStrictEqual(plain(color.value), {
    colorSpace: 'lab',
    components: [60.17, 90, -60.5],
  });
  assert.strictEqual(sd.tokenMap.get('{border.width}').value, '4px');
  assert.strictEqual(sd.tokenMap.get('{border.style}').value, 'solid');
});

test('expand.exclude selects which tokens keep their array values un-itemized', async () => {
  const sd = await init({
    tokens: mixedTokens(),
    expand: { exclude: ['strokeStyle'] },
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{fade.delay}',
    '{fade.duration}',
    '{fade.timingFunction.1}',
    '{fade.timingFunction.2}',
    '{fade.timingFunction.3}',
    '{fade.timingFunction.4}',
    '{stroke}',
  ]);

  // excluded strokeStyle token is not expanded at all: array value stays intact
  const stroke = sd.tokenMap.get('{stroke}');
  assert.strictEqual(stroke.type, 'strokeStyle');
  assert.deepStrictEqual(stroke.value.dashArray, ['0.5rem', '0.25rem']);
  assert.strictEqual(stroke.value.lineCap, 'round');

  // the transition's timingFunction array is itemized with mapped types
  const points = [0.42, 0, 0.58, 1];
  for (let i = 0; i < points.length; i++) {
    const token = sd.tokenMap.get(`{fade.timingFunction.${i + 1}}`);
    assert.strictEqual(token.value, points[i]);
    assert.strictEqual(token.type, 'cubicBezier');
  }
  assert.strictEqual(sd.tokenMap.get('{fade.delay}').value, '0ms');
  assert.strictEqual(sd.tokenMap.get('{fade.delay}').type, 'duration');
  assert.strictEqual(sd.tokenMap.get('{fade.duration}').value, '300ms');
});

test('expand.include as a function also governs array itemization', async () => {
  const sd = await init({
    tokens: mixedTokens(),
    expand: {
      include: (token) => ['strokeStyle', 'dimension'].includes(token.type),
    },
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{fade}',
    '{stroke.dashArray.1}',
    '{stroke.dashArray.2}',
    '{stroke.lineCap}',
  ]);

  assert.strictEqual(sd.tokenMap.get('{stroke.dashArray.1}').value, '0.5rem');
  assert.strictEqual(sd.tokenMap.get('{stroke.dashArray.1}').type, 'dimension');
  assert.strictEqual(sd.tokenMap.get('{stroke.dashArray.2}').value, '0.25rem');
  assert.strictEqual(sd.tokenMap.get('{fade}').type, 'transition');
  assert.deepStrictEqual(sd.tokenMap.get('{fade}').value.timingFunction, [0.42, 0, 0.58, 1]);
});

test('expand.typesMap determines the type of expanded array item tokens', async () => {
  const sd = await init({
    tokens: {
      stroke: {
        type: 'strokeStyle',
        value: { dashArray: ['0.5rem', '0.25rem'], lineCap: 'round' },
      },
    },
    expand: { typesMap: { strokeStyle: { dashArray: 'number' } } },
  });

  assert.deepStrictEqual(keysOf(sd.tokenMap), [
    '{stroke.dashArray.1}',
    '{stroke.dashArray.2}',
    '{stroke.lineCap}',
  ]);

  const dash1 = sd.tokenMap.get('{stroke.dashArray.1}');
  assert.strictEqual(dash1.key, '{stroke.dashArray.1}');
  assert.strictEqual(dash1.type, 'number');
  assert.strictEqual(dash1.value, '0.5rem');

  const dash2 = sd.tokenMap.get('{stroke.dashArray.2}');
  assert.strictEqual(dash2.type, 'number');
  assert.strictEqual(dash2.value, '0.25rem');

  // unmapped properties keep their default mapping
  assert.strictEqual(sd.tokenMap.get('{stroke.lineCap}').type, 'lineCap');
  assert.strictEqual(sd.tokenMap.get('{stroke.lineCap}').value, 'round');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const { default: StyleDictionary } = await import(
  pathToFileURL(`${process.cwd()}/lib/StyleDictionary.js`).href
);

const init = async (config) => {
  const sd = new StyleDictionary(config);
  await sd.hasInitialized;
  return sd;
};

const keysOf = (map) => [...map.keys()].sort();

const plain = (value) => JSON.parse(JSON.stringify(value));

const strokeInput = () => ({
  stroke: {
    type: 'strokeStyle',
    value: { dashArray: ['0.5rem', '0.25rem'], lineCap: 'round' },
  },
});

const mixedTokens = () => ({
  ...strokeInput(),
  fade: {
    type: 'transition',
    value: {
      duration: '300ms',
      delay: '0ms',
