test('platform-level expand config object applies include and typesMap to array expansion', async () => {
  const sd = await init({
    tokens: mixedTokens(),
    platforms: {
      css: {
        expand: {
          include: ['strokeStyle', 'dimension'],
          typesMap: { strokeStyle: { dashArray: 'string' } },
        },
      },
      js: {},
    },
  });

  const css = await sd.getPlatformTokens('css');
  assert.deepStrictEqual(keysOf(css.tokenMap), [
    '{fade}',
    '{stroke.dashArray.1}',
    '{stroke.dashArray.2}',
    '{stroke.lineCap}',
  ]);

  const dash1 = css.tokenMap.get('{stroke.dashArray.1}');
  assert.strictEqual(dash1.value, '0.5rem');
  assert.strictEqual(dash1.type, 'string');
  assert.deepStrictEqual(dash1.path, ['stroke', 'dashArray', '1']);

  const dash2 = css.tokenMap.get('{stroke.dashArray.2}');
  assert.strictEqual(dash2.value, '0.25rem');
  assert.strictEqual(dash2.type, 'string');
  assert.deepStrictEqual(dash2.path, ['stroke', 'dashArray', '2']);

  // transition excluded by the platform include config: array value stays intact
  const fade = css.tokenMap.get('{fade}');
  assert.strictEqual(fade.type, 'transition');
  assert.deepStrictEqual(plain(fade.value), {
    duration: '300ms',
    delay: '0ms',
    timingFunction: [0.42, 0, 0.58, 1],
  });

  // platform without expand config exports untouched tokens
  const js = await sd.getPlatformTokens('js');
  assert.deepStrictEqual(keysOf(js.tokenMap), ['{fade}', '{stroke}']);
  assert.deepStrictEqual(js.tokenMap.get('{stroke}').value.dashArray, ['0.5rem', '0.25rem']);
  assert.deepStrictEqual(js.tokenMap.get('{fade}').value.timingFunction, [0.42, 0, 0.58, 1]);
});
